  { ?var1  wdt:P31   wde:Q15284 ;
           ?var3     wde:Q142 ;
           wdt:P625  ?var2
  }

PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  (isIRI(?var1) AS ?var2) (isIRI(?var3) AS ?var4)
WHERE
  { { SELECT  ?var5 ?var1 ?var3
      WHERE
        { ?var5  wdt:P31   wde:Q15145593 ;
                 wdt:P131  ?var1 ;
                 wdt:P17   ?var3
        }
      LIMIT   1000
    }
  }

positive_queries:
PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?var1 ?var2Label (?var3 AS ?var4) ?var5 ?var6
WHERE
  { { SELECT  (SUM(?var3) AS ?var6)
      WHERE
        { ?var1  wdt:P1082  ?var3 ;
                 wdt:P31    wde:Q185441
        }
    }
  }

PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  (COUNT(DISTINCT ?var1) AS ?var2)
WHERE
  { VALUES ?var1 { wde:Q3915 }
    ?var1 wdt:P31/(wdt:P279)* wde:Q17334923
    FILTER NOT EXISTS { ?var1  wdt:P1566  ?var3 }
  }

SELECT  (SUM(?var1) AS ?var2)
WHERE
  { ?var3 <http://www.wikidata.org/prop/P1367>/<http://www.wikidata.org/prop/qualifier/P1114> ?var1 }

PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT DISTINCT  (COUNT(DISTINCT ?var1) AS ?var2)
WHERE
  { { ?var3  wdt:P31     <http://www.wikidata.org/wiki/Q2095> ;
             rdfs:label  ?var1
      FILTER ( lang(?var1) = "en" )
    }
  }

negative_queries:
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?var1 ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { ?var1  wdt:P31     wde:Q5 ;
           wdt:P569    ?var4 ;
           wdt:P570    ?var5 ;
           wdt:P19     ?var6 ;
           wdt:P646    ?var3 ;
           rdfs:label  ?var2
    FILTER ( lang(?var2) = "en" )
    FILTER ( ?var4 < "1900-01-01T00:00:00Z"^^xsd:dateTime )
  }

PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  url:  <http://schema.org/>

SELECT  ?var1Label ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { OPTIONAL
      { wde:Q1074656  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var7 )
        VALUES ( ?var7 ?var8 ) {
          ( "undefined" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
        }
      }
    OPTIONAL
      { wde:Q1074656  wdt:P18  ?var3 }
    OPTIONAL
      { wde:Q1074656  <urn:dboabstract>  ?var2
        FILTER ( lang(?var2) = "undefined" )
      }
    OPTIONAL
      { wde:Q1074656  wdt:P625  ?var4 }
    OPTIONAL
      { ?var6  rdf:type        url:Article ;
               url:about       wde:Q1074656 ;
               url:inLanguage  "undefined" ;
               url:isPartOf    <https://undefined.wikipedia.org/>
      }
  }
ORDER BY ASC(?var8)

